begin;
create temp table _had_parking on commit drop as select id from public.areas where parking_lat is not null;
update public.areas set parking_lat=36.004647, parking_lng=-93.292572, parking_name='Horseshoe Canyon Ranch parking by the Trading Post (check-in, day-use fee)' where path <@ (select path from public.areas where id='ar_horseshoe_canyon_ranch') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 36.004647) / 2), 2) + cos(radians(36.004647)) * cos(radians(lat)) * power(sin(radians(lng - -93.292572) / 2), 2))) <= 4);
